            T1 = X; T2 = Y; break;
        case 6:
            T1 = Y; T2 = Z; break;
        default:
            T1 = 0; T2 = 0; break;
    }

    // Clamp to linear range
    if (T1 + T2 > (float)PWM_PERIOD) {
        float scale = (float)PWM_PERIOD / (T1 + T2);
        T1 *= scale;
        T2 *= scale;
